 bool ChangeLanguage(string language){
  string previousLanguage=UiText.Language;MainWindow? replacement=null;bool saved=false;
  try{Stop();UiText.SetLanguage(language);saved=true;replacement=new MainWindow();
   replacement.Project=Project;replacement.Dance=Dance;replacement.CameraClip=CameraClip;replacement.Audio=Audio;replacement.Rig=Rig;replacement.projectPath=projectPath;replacement.dirty=dirty;replacement.cursor=cursor;replacement.modRoot=modRoot;
   if(Rig!=null){replacement.stage.SetRig(Rig);replacement.camera.SetRig(Rig);replacement.updating=true;replacement.bones.ItemsSource=Rig.Names.Select((name,i)=>new BoneItem(i,name)).ToList();replacement.updating=false;}
   replacement.faceTools.Adopt(faceTools);replacement.faceZoom.IsChecked=faceZoom.IsChecked;replacement.timelineTabs.SelectedIndex=timelineTabs.SelectedIndex;replacement.timeline.Axis.CopyFrom(timeline.Axis);replacement.RefreshFields();replacement.UpdatePreview();replacement.Left=Left;replacement.Top=Top;replacement.WindowStartupLocation=WindowStartupLocation.Manual;replacement.Width=Width;replacement.Height=Height;
   replacement.Show();if(Application.Current.MainWindow==this)Application.Current.MainWindow=replacement;dirty=false;Close();return true;
  }catch(Exception e){if(replacement!=null){if(Application.Current.MainWindow==replacement)Application.Current.MainWindow=this;replacement.dirty=false;replacement.Close();}if(saved){try{UiText.SetLanguage(previousLanguage);}catch{UiText.RestoreSelection(previousLanguage);}}MessageBox.Show(this,e.Message,Brand.Name,MessageBoxButton.OK,MessageBoxImage.Warning);return false;}
