 void StartSound(){if(!playing||soundStarted||Audio==null)return;double source=Project.Audio.SourceTime(cursor);if(source<Project.Audio.In||source>=Project.Audio.Out)return;sound.Play(Audio,source,cursor,Project.Audio.Out,silentTest?0:Project.PreviewVolume);soundStarted=true;}
 void Stop(){try{if(playing&&sound.Active)cursor=sound.Position;}catch(IOException){status.Text=UiText.T("t0242");}finally{playing=false;clock.Stop();sound.Dispose();play.Content=UiText.T("t0142");}}
 void Tick(){if(!playing)return;try{double proposed=anchor+clock.Elapsed.TotalSeconds;if(sound.Active&&sound.Position<sound.End-1.0/(Audio?.SampleRate??48000))cursor=sound.Position;else{if(sound.Active){anchor=cursor;sound.Dispose();clock.Restart();proposed=cursor;}cursor=proposed;}StartSound();if(cursor>=Project.ExportOut){Stop();cursor=Project.ExportOut;}UpdatePreview();}catch(Exception ex){Stop();status.Text=UiText.T("t0243")+UiText.Error(ex.Message);}}
 public void CleanForSmoke(){dirty=false;}
 public async Task<object> TransportSmoke(){
  double span=Project.ExportOut-Project.ExportIn;if(span<.5)throw new InvalidOperationException("Transport smoke requires at least 0.5 seconds of export range.");double start=Project.ExportIn+Math.Min(.5,span*.1);silentTest=true;Seek(start);Toggle();await Task.Delay(240);bool advancing=cursor>start+.05&&cursor<Math.Min(Project.ExportOut,start+2);
  bool hardwareClock=sound.Active;double observed=cursor;Stop();Seek(start+1.0/Project.DanceOutputFps.Resolve(Dance,Project.Dance));
  if(!advancing)throw new Exception(UiText.T("t0244"));
  if(Math.Abs(cursor-(start+1.0/Project.DanceOutputFps.Resolve(Dance,Project.Dance)))>1e-8)throw new Exception(UiText.T("t0245"));
  silentTest=false;dirty=false;return new {passed=true,hardwareClock,observedTimeline=observed,frameStep=1.0/Project.DanceOutputFps.Resolve(Dance,Project.Dance),silentAudio=true};
 }
